<?php
require_once __DIR__.'/../../app/bootstrap.php'; require_role(['system_admin','cooperative_manager']);
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');} verify_csrf(); $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); if(!$id){flash('error','Invalid member selected.');redirect('../members.php');}
try{$pdo=db();$st=$pdo->prepare('SELECT id,cooperative_id,member_number FROM members WHERE id=?');$st->execute([$id]);$m=$st->fetch();if(!$m){flash('error','Member record not found.');redirect('../members.php');}if(current_user()['role']!=='system_admin'&&(int)$m['cooperative_id']!==(int)current_user()['cooperative_id']){http_response_code(403);exit('Access denied.');}$pdo->beginTransaction();$pdo->prepare('INSERT INTO audit_logs (user_id,action,entity_type,entity_id,details,ip_address) VALUES (?,?,?,?,?,?)')->execute([current_user()['id'],'delete','member',$id,json_encode(['member_number'=>$m['member_number']]),$_SERVER['REMOTE_ADDR']??null]);$pdo->prepare('DELETE FROM members WHERE id=?')->execute([$id]);$pdo->commit();flash('success','Member record deleted.');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error','Could not delete the member record.');}redirect('../members.php');
